/**
 * import-mechanic-kpi.js — loads a periodic technician KPI report (an
 * external attendance/billing export, not generated by this platform) into
 * mechanic_kpi_snapshots, matched against the real mechanic record each
 * row belongs to.
 *
 * Matching is by employee_code (the source TN-code, e.g. "TN0269") against
 * the src_id the original Oracle mechanics import stamped into
 * mechanics.notes — the same join key scripts/oracle-migration/migrate.mjs
 * uses. Falling back to an exact full_name match only when no TN-code hit
 * is found, and logging every unmatched row loudly rather than silently
 * dropping it or inventing a mechanic to attach it to — this is real
 * people's real billed-hours data, so a silent wrong match is worse than
 * a loud skip.
 *
 * Usage:
 *   node scripts/import-mechanic-kpi.js <csv-path> <period_start> <period_end> [--dry-run] [--source=label]
 *   node scripts/import-mechanic-kpi.js scripts/data/technicians_kpi_2026-07.csv 2026-07-01 2026-07-31
 *
 * `source` defaults to kpi_report_<period_start month>; pass --source=xxx to
 * override (used to tag modeled/estimated historical months distinctly from
 * the one real report — see scripts/generate-historical-kpi.js).
 */
import fs from 'fs';
import { query, execute } from '../src/lib/database.js';

const [, , csvPathArg, periodStartArg, periodEndArg, ...rest] = process.argv;
const dryRun = rest.includes('--dry-run');
const sourceArg = rest.find(a => a.startsWith('--source='))?.split('=')[1];
const source = sourceArg || `kpi_report_${(periodStartArg || '').slice(0, 7)}`;

if (!csvPathArg || !periodStartArg || !periodEndArg) {
  console.error('Usage: node scripts/import-mechanic-kpi.js <csv-path> <period_start> <period_end> [--dry-run] [--source=label]');
  process.exit(1);
}
if (Number.isNaN(Date.parse(periodStartArg)) || Number.isNaN(Date.parse(periodEndArg))) {
  console.error('period_start/period_end must be YYYY-MM-DD');
  process.exit(1);
}

function parseCsv(text) {
  const lines = text.trim().split('\n');
  const header = lines[0].split(',');
  return lines.slice(1).map(line => {
    const cells = line.split(',');
    const row = {};
    header.forEach((h, i) => { row[h.trim()] = (cells[i] ?? '').trim(); });
    return row;
  });
}

const num = v => (v === '' || v == null ? null : Number(v));

async function main() {
  const csv = fs.readFileSync(csvPathArg, 'utf8');
  const rows = parseCsv(csv);
  console.log(`Loaded ${rows.length} rows from ${csvPathArg}`);
  console.log(`Period: ${periodStartArg} to ${periodEndArg}${dryRun ? ' (dry run — nothing will be written)' : ''}`);
  console.log(`Source label: ${source}`);
  console.log('');

  const [{ id: workshopId } = {}] = await query('SELECT id FROM workshops LIMIT 1');
  if (!workshopId) throw new Error('No workshop found');

  // Idempotent re-runs: a second import of the same period+source used to just
  // append a second copy of every row (the table intentionally has no unique
  // constraint on mechanic_id+period, since a few real mechanics genuinely
  // have two source rows in one period — see the migration's comment). So a
  // plain re-run silently doubled the report instead of refreshing it.
  // Replacing by (period, source) keeps that legitimate case working while
  // making "ran the same file twice" a no-op instead of a duplicate.
  if (!dryRun) {
    const del = await execute(
      `DELETE FROM mechanic_kpi_snapshots WHERE workshop_id = ? AND period_start = ? AND period_end = ? AND source = ?`,
      [workshopId, periodStartArg, periodEndArg, source]
    );
    if (del.affectedRows) console.log(`Replacing ${del.affectedRows} existing row(s) for this period+source before re-importing.\n`);
  }

  let matchedByCode = 0, matchedByName = 0, unmatched = 0, inserted = 0;
  const unmatchedRows = [];

  for (const r of rows) {
    const tnCode = r.tn_code;
    const name = r.technician;

    let [mech] = await query(
      `SELECT id FROM mechanics
        WHERE workshop_id = ? AND JSON_VALID(notes) = 1
          AND JSON_UNQUOTE(JSON_EXTRACT(notes, '$.src_id')) = ?
        LIMIT 1`,
      [workshopId, tnCode]
    );

    let matchType = 'code';
    if (!mech) {
      [mech] = await query(
        `SELECT id FROM mechanics WHERE workshop_id = ? AND full_name = ? LIMIT 1`,
        [workshopId, name]
      );
      matchType = 'name';
    }

    if (!mech) {
      unmatched++;
      unmatchedRows.push(`  [${r.sno}] ${name} (${tnCode}) — no mechanic record found by code or exact name`);
      continue;
    }

    if (matchType === 'code') matchedByCode++; else matchedByName++;

    if (!dryRun) {
      await execute(
        `INSERT INTO mechanic_kpi_snapshots
           (workshop_id, mechanic_id, period_start, period_end, employee_code, designation,
            days_present, avail_hrs, ot_hrs, total_hrs, worked_hrs, prod_hrs_pct, idle_hrs_pct,
            billed_value, billed_hrs, billed_hours, utilization_pct, productivity_pct, efficiency_pct,
            source)
         VALUES (?,?,?,?,?,?, ?,?,?,?,?,?,?, ?,?,?, ?,?,?, ?)`,
        [
          workshopId, mech.id, periodStartArg, periodEndArg, tnCode, r.designation,
          num(r.days_present), num(r.avail_hrs), num(r.ot), num(r.total_hrs), num(r.worked_hrs),
          num(r.prod_hrs_pct), num(r.idle_hrs_pct),
          num(r.billed_value), num(r.billed_hrs), num(r.billed_hours),
          num(r.u_pct), num(r.p_pct), num(r.e_pct),
          source,
        ]
      );
    }
    inserted++;
  }

  console.log(`Matched by TN-code: ${matchedByCode}`);
  console.log(`Matched by exact name (no code hit): ${matchedByName}`);
  console.log(`Unmatched (skipped): ${unmatched}`);
  if (unmatchedRows.length) {
    console.log('\nUnmatched rows — these need a manual look before re-running:');
    unmatchedRows.forEach(l => console.log(l));
  }
  console.log(`\n${dryRun ? 'Would insert' : 'Inserted'}: ${inserted} snapshot rows`);
  process.exit(0);
}

main().catch(err => {
  console.error('Import failed:', err.message);
  process.exit(1);
});
